contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking the amount to send as a parameter
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        // observe pot before the call and bank address
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        address bankAddr = c.bank(); if (__ESBMC_reverted()) return;

        bool reverted;
        // perform the state-changing call: send amount to c.play()
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;

        // General rule asserted for all inputs:
        // - If the call reverted then nothing about potAfter is required here (revert allowed).
        // - If the call did not revert then amount must have been exactly C.TICKET_AMOUNT (10)
        //   and potAfter is either potBefore + amount (no payout) or 0 (payout occurred).
        // We express: if not reverted then amount equals 10 and (potAfter == potBefore + amount || potAfter == 0)
        assert(reverted || (amount == 10 && (potAfter == potBefore + amount || potAfter == 0)));
    }

    // receive to accept refunds/payouts from c
    receive() external payable {}
}

